import{z as m,x as A,o as l,c as B,q as r,j as i,D as t,d as E,s as n,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"服务成本模型","description":"","frontmatter":{"title":"服务成本模型","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/serving-cost-model.md","filePath":"llm/serving-cost-model.md","lastUpdated":1791063341000}'),p={name:"llm/serving-cost-model.md"};function d(P,e,h,T,k,C){const o=A("Mermaid");return l(),B("div",null,[e[2]||(e[2]=r('<h1 id="服务成本模型" tabindex="-1">服务成本模型 <a class="header-anchor" href="#服务成本模型" aria-label="Permalink to &quot;服务成本模型&quot;">​</a></h1><div class="epigraph"><p>token 价格不是模型质量的函数，而是 GPU 时间除以有效吞吐，再叠上利用率、电与失败重试。</p><footer>—— 对照 Pope 等对推理扩展的阶段划分，以及 Splitwise 把 prefill 与 decode 分到不同机器的成本动机（Patel et al.）</footer></div><p><a href="/llm/energy-per-token">上一课</a>给出每 token 焦耳。财务账单通常由 <em>租用的加速器小时</em> 主导，电是第二项。本课把吞吐、利用率、阶段拆分收成单位 token 成本，使「再开一个 \\(N=8\\) 投票」能写成美元，而不是口号。Splitwise（Patel 等）把 prefill 与 decode 拆机，正是因为两段的屋顶不同、机器单价不同。本课写模型，不写某一云厂商价目表当科学常数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有效成本</p> \\[C_{\\mathrm{tok}}\\approx\\frac{C_{\\mathrm{GPU-h}}/3600}{\\eta\\cdot \\mathrm{TPS}}+C_{\\mathrm{energy}}(E_{\\mathrm{tok}}), \\]<p>其中 TPS 是集群级 token/s，\\(\\eta\\) 是相对峰值吞吐的利用率（排队、气泡、失败重试、投机拒绝都进 \\(1-\\eta\\)）。缺口是：产品按提示 token 与生成 token 分开计价，成本也必须分阶段——prefill 算力密、decode 带宽密，混用同一 \\(C_{\\mathrm{GPU-h}}\\) 与同一 TPS 会把长提示用户补贴给长生成用户，或反过来。</p><p>多样本：\\(N\\) 条生成把分母上的「用户可见 token」变成 \\(1/N\\) 的有效产出（若只交付一条）。自洽的准确率增益要拿 \\(N\\times C_{\\mathrm{tok}}\\) 比。这是上一课程留下的账，现在可以算。</p><p><span class="marginnote">排队时间消耗租时但不产 token，全部进 \\(\\eta\\)。只在 GPU busy 时测 TPS 会低估真实 \\(C_{\\mathrm{tok}}\\)。SLA 拒请求若仍占着 KV 槽，同样进利用率。</span></p><p><span class="marginnote">直觉类比：花 \\(N\\) 份 GPU 时间生成 \\(N\\) 个候选、只交付最好的 1 条，就像买 \\(N\\) 张彩票只兑奖最高的那张——单张价格没变，但「中一次」的真实成本是 \\(N\\) 倍，所以收益要拿 \\(N\\times C_{\\mathrm{tok}}\\) 来比，而不是只看最好那次的成绩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分两项吞吐：TTFT 路径的 prompt-TPS，TPOT 路径的 gen-TPS。机器池若分离，用各自的 \\(C_{\\mathrm{GPU-h}}\\) 与 \\(\\eta\\)。若混合，用拐点课的工作点：decode 池保持在 \\(B^\\star\\) 左侧以满足 TPOT，多余算力才去 prefill。投机：gen-TPS 用 <em>接受的</em> token，成本含草稿。KV 容量限制最大 \\(B\\)，从而限制 TPS 上限——成本模型必须受<a href="/llm/kv-cache-size-math">容量公式</a>约束，不能假设线性加机器就线性加 TPS（互连与调度会弯折，后课程通信课再写）。</p>',12)),(l(),i(s,null,{default:t(()=>[n(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20RENT%5B%22%E5%8A%A0%E9%80%9F%E5%99%A8%E5%B0%8F%E6%97%B6%E4%BB%B7%22%5D%20--%3E%20C%5B%22C_tok%22%5D%0A%20%20TPS%5B%22%E6%9C%89%E6%95%88%20token%2Fs%22%5D%20--%3E%20C%0A%20%20ETA%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%20%CE%B7%22%5D%20--%3E%20C%0A%20%20E%5B%22E_tok%20%C3%97%20%E7%94%B5%E4%BB%B7%22%5D%20--%3E%20C%0A%20%20N%5B%22%E4%BA%A4%E4%BB%98%201%20%2F%20%E7%94%9F%E6%88%90%20N%22%5D%20--%3E%20TPS%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"\\(C_{\\mathrm{tok}}\\) 对 \\(\\eta\\) 极敏感：空闲热备换尾延迟，直接抬成本。预热权重、长上下文常驻 KV，都是用容量换延迟。Splitwise 的逻辑是：prefill 买算力型、decode 买带宽/显存型，避免在贵的机器上跑错屋顶。成本模型若只有一个池，至少要在表上分列两段的边际成本，否则定价与调度无法对齐。",-1)),e[5]||(e[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：设 GPU 小时价 8 美元、集群 gen-TPS 为 5000。\\(\\eta=0.9\\) 时每百万生成 token 约 \\(8/(3600\\times 0.9\\times 5000)\\times 10^6\\approx 0.49\\) 美元；\\(\\eta\\) 掉到 0.45（一半时间耗在排队、重试、气泡），同一公式立刻变成约 0.98 美元——成本翻倍，而模型一行代码没改。")],-1)),e[6]||(e[6]=a("p",null,"两段各自贴着哪面「屋顶」跑，决定了该买什么机器：",-1)),(l(),i(s,null,{default:t(()=>[n(o,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22prefill%20%E9%98%B6%E6%AE%B5%22%5D%20--%3E%20P1%5B%22%E6%95%B4%E6%AE%B5%E6%8F%90%E7%A4%BA%E4%B8%80%E6%AC%A1%E5%B9%B6%E8%A1%8C%E7%AE%97%3A%20%E7%AE%97%E5%8A%9B%E5%AF%86%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E9%85%8D%E7%AE%97%E5%8A%9B%E5%9E%8B%E6%9C%BA%E5%99%A8%2C%20%E6%8D%A2%20TTFT%22%5D%0A%20%20D%5B%22decode%20%E9%98%B6%E6%AE%B5%22%5D%20--%3E%20D1%5B%22%E6%AF%8F%E6%AD%A5%E8%AF%BB%E5%85%A8%E9%87%8F%20KV%3A%20%E5%B8%A6%E5%AE%BD%2F%E6%98%BE%E5%AD%98%E5%AF%86%22%5D%0A%20%20D1%20--%3E%20D2%5B%22%E9%85%8D%E5%B8%A6%E5%AE%BD%E5%9E%8B%E6%9C%BA%E5%99%A8%2C%20%E7%A8%B3%20TPOT%22%5D%0A%20%20P2%20--%3E%20S%5B%22%E4%B8%A4%E6%B1%A0%E5%90%84%E6%8C%89%E5%B1%8B%E9%A1%B6%E9%85%8D%E6%9C%BA%E5%99%A8%E4%B8%8E%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%0A%20%20D2%20--%3E%20S%0A%20%20S%20--%3E%20O%5B%22%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%E5%88%86%E5%88%97%2C%20%E5%AE%9A%E4%BB%B7%E4%B8%8E%E8%B0%83%E5%BA%A6%E5%AF%B9%E9%BD%90%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把公开聊天产品的每百万 token 报价当成你的 \\(C_{\\mathrm{tok}}\\)：那是含毛利、缓存命中与套餐的价格。不要忽略失败重试与安全拒绝的 token。后课把 \\(n\\) 拉长：成本与显存都变成曲线，而不是一个点。</p><p><span class="marginnote">常见误区：初学者容易把云厂商「每百万 token 多少元」的牌价直接当自己的成本模型，实际上那里面含毛利、缓存折扣与套餐结构。自建服务要回到租时、利用率与分阶段吞吐来算，否则一上缓存或一拆池，账就对不上了。</span></p><p>出处：Pope et al., 2022；Patel et al., Splitwise（高效生成式 LLM 推理的阶段拆分）。云价格只作数量级对照，不列入公式常数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(C_{\\mathrm{tok}}\\) 是租时除以有效吞吐，再加电；\\(\\eta\\) 含排队与重试。</li><li>提示与生成必须分列；混池要用工作点约束。</li><li>多样本把用户可见产出除以 \\(N\\)。</li><li>容量墙给出 TPS 上限，成本模型不得假设无限线性扩展。</li><li>拆分 prefill/decode 是为了让机器单价对齐屋顶。</li><li>下一课：长上下文下显存随 \\(n\\) 的曲线。</li><li>出处：Pope et al., 2022；Patel et al., Splitwise。</li></ul>',6))])}const f=m(p,[["render",d]]);export{D as __pageData,f as default};
